const headers = $input.first().json.headers || {};
const h = Object.fromEntries(
  Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v])
);

// Troque pelo mesmo token que vai em js/n8n-config.js
const expected = 'movfit_proxy_k7x9m2pQ4wR9';
const got = h['x-movfit-proxy'] || '';

if (got !== expected) {
  return [{ json: { ok: false, error: 'Unauthorized' } }];
}

const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    ok: true,
    empresaId: String(body.empresaId || '1'),
  }
}];
